    ev.push({ player: id, day: first, segment: seg });
    for (let d = 1; first + d < today; d++) if (rnd() < keep * (d === 1 ? 0.36 : 0.09 + 0.25 / d)) ev.push({ player: id, day: first + d, segment: seg });
